  const audience = String(resolved.audience);

  return {
    description: `Summarize "${topic}" for ${audience}.`,
    messages: [
      {
        role: 'user',
        content: {
          type: 'text',
          text: `Please summarize the following topic: ${topic}\nTarget audience: ${audience}`,
        },
      },
    ],
  };
}
